'use strict';
const app=document.querySelector('#app'),dialog=document.querySelector('#dialog');
let session={authenticated:false},catalog=[],adminCatalog=[],current=null,editor=null,editorId=null,editorVersion=null,autosaveTimer=null,routeGeneration=0;
const typeNames={single:'Opción única',multiple:'Selección múltiple',boolean:'Verdadero o falso',text:'Respuesta corta',long_text:'Respuesta larga',number:'Respuesta numérica',matching:'Relacionar columnas',table:'Tabla de respuestas',image_mark:'Marcar una imagen'};
const icons={book:'M4 4h6a3 3 0 0 1 3 3v14a4 4 0 0 0-4-3H4z M20 4h-4a3 3 0 0 0-3 3v14a4 4 0 0 1 4-3h3z',grid:'M3 3h7v7H3z M14 3h7v7h-7z M3 14h7v7H3z M14 14h7v7h-7z',check:'M5 12l4 4L19 6',arrow:'M5 12h14 M13 6l6 6-6 6',back:'M19 12H5 M11 6l-6 6 6 6',clock:'M12 8v5l3 2 M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2 M13 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0 M16 3a4 4 0 0 1 0 8 M22 21v-2a4 4 0 0 0-3-3.9',file:'M14 2H6v20h14V8z M14 2v6h6 M9 12h6 M9 16h6',plus:'M12 5v14 M5 12h14',chart:'M4 20V4 M4 20h17 M8 16v-5 M13 16V7 M18 16V3',trash:'M3 6h18M9 6V3h6v3M5 6l1 15h12l1-15M10 10v7M14 10v7',logout:'M9 4H4v16h5 M10 12h11 M16 7l5 5-5 5',lock:'M5 10h14v11H5z M8 10V6a4 4 0 0 1 8 0v4',download:'M12 3v12 M7 10l5 5 5-5 M4 17v4h16v-4',edit:'M15 4l5 5 M4 20l4-1L21 6l-5-5L3 14z'};
const icon=(name,size=20)=>`<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.file}"/></svg>`;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const dt=v=>v?new Date(v).toLocaleDateString('es-MX',{day:'2-digit',month:'short',year:'numeric'}):'—';
const pct=v=>v===null||v===undefined?'—':`${Number(v).toLocaleString('es-MX',{maximumFractionDigits:1})}%`;
const brand=()=>`<a class="brand" href="#inicio"><span class="brand-mark">MESA</span><span>Formación</span></a>`;
function toast(message){const t=document.querySelector('#toast');t.textContent=message;t.classList.add('visible');setTimeout(()=>t.classList.remove('visible'),5000)}
async function downloadEvaluationPdf(button){
 let writable;
 const original=button.innerHTML;
 try{
  button.disabled=true;
  const filename=(button.dataset.filename||'evaluacion.pdf').replace(/[<>:"/\\|?*\x00-\x1f]/g,'-');
  let handle=null;
  if(window.isSecureContext && typeof window.showSaveFilePicker==='function'){
   try{handle=await window.showSaveFilePicker({id:'mesa-evaluaciones',suggestedName:filename,types:[{description:'Documento PDF',accept:{'application/pdf':['.pdf']}}]});}
   catch(e){if(e.name==='AbortError')return;if(e.name!=='SecurityError' && e.name!=='NotSupportedError')throw e;}
  }
  button.textContent='Preparando PDF…';
  const kind=button.dataset.kind==='exams'?'exams':'results';
  const response=await fetch(`/api/admin/${kind}/${encodeURIComponent(button.dataset.id)}/pdf`);
  if(!response.ok){const data=await response.json();throw Error(data.error||'No se pudo generar el PDF.');}
  const blob=await response.blob();
  if(handle){writable=await handle.createWritable();await writable.write(blob);await writable.close();writable=null;toast('PDF guardado en la carpeta seleccionada.');}
  else{
   const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);
   toast('Descarga iniciada. Para elegir carpeta, activa «Preguntar dónde guardar cada archivo» en tu navegador.');
  }
 }catch(e){if(writable)try{await writable.abort();}catch{}if(e.name!=='AbortError')error(e.message);}
 finally{button.disabled=false;button.innerHTML=original;}
}
async function api(path,method='GET',body){const r=await fetch('/api'+path,{method,headers:{...(body?{'Content-Type':'application/json'}:{}),...(session.csrf?{'X-CSRF-Token':session.csrf}:{})},...(body?{body:JSON.stringify(body)}:{})});const data=await r.json();if(!r.ok)throw Error(data.error||'No fue posible completar la acción.');return data}
function error(message){const box=document.querySelector('#user-form-error')||document.querySelector('#form-error');if(box){box.innerHTML=`<div class="notice error" role="alert">${esc(message)}</div>`;box.scrollIntoView({block:'nearest',behavior:'smooth'})}else toast(message)}
const publicLayout=content=>`<header class="public-header">${brand()}<nav><a href="#inicio">Exámenes disponibles</a><a class="button small" href="#dashboard">${icon('lock',14)} Administración</a></nav></header><main class="page">${content}</main><footer class="public-footer"><span>Manufacturas Especializadas S.A. · Capacitación y desarrollo</span><span>MESA Formación · ${new Date().getFullYear()}</span></footer>`;
function adminLayout(content,active='dashboard'){return `<div class="admin"><aside class="sidebar">${brand()}<div class="nav-label">ESPACIO DE CAPACITACIÓN</div><nav>${[['dashboard','grid','Dashboard'],['exams','book','Exámenes'],['results','chart','Resultados'],...(session.manage_users?[['users','users','Usuarios']]:[])].map(([id,ic,label])=>`<a href="#${id}" class="${active===id?'active':''}">${icon(ic,18)}${label}</a>`).join('')}</nav><div class="sidebar-note"><strong>Aprendizaje que se mide.</strong>Da seguimiento a la formación de tu equipo y nuevos talentos.</div><div class="sidebar-bottom">${esc(session.username)}<button class="quiet" data-action="password">Cambiar contraseña</button><button class="quiet" data-action="logout">${icon('logout',15)}Cerrar sesión</button></div></aside><div class="admin-body"><header class="admin-header"><span>Capacitación <span aria-hidden="true">/</span> ${active==='dashboard'?'Vista general':active==='exams'?'Biblioteca de exámenes':active==='users'?'Usuarios':'Resultados'}</span><div class="user"><a href="#inicio">Ver portal</a><span class="avatar">${esc((session.username||'AD').slice(0,2).toUpperCase())}</span><span>${esc(session.username)}</span></div></header><main class="admin-content">${content}</main></div></div>`}
const field=(label,name,value='',type='text',extra='')=>`<label class="field">${esc(label)}<input type="${type}" name="${esc(name)}" value="${esc(value)}" ${extra}></label>`;
function examDocumentSettings(exam){return {top_text:'EVALUACIÓN DE COMPRENSIÓN',revision_text:'Rev. de Evaluación: '+(exam.revision?.match(/Rev\.\s*(\d+)/i)?.[1]||'00'),footer_left:'Fecha de Elaboración 09/07/2025, Rev. 01',footer_center:'Manufacturas Especializadas S.A.',footer_right:'FO-RH-14',...exam.document};}
function examDocumentHeader(exam,heading='h2'){const d=examDocumentSettings(exam);return `<header class="exam-document-header"><img src="/static/branding/mesa.svg" alt="MESA"><div class="exam-document-title"><span>${esc(d.top_text)}</span><${heading} class="document-exam-title">${esc(exam.title||'Título de la evaluación')}</${heading}></div><div class="exam-document-revision">${esc(d.revision_text)}</div></header>`;}
function examDocumentFooter(exam){const d=examDocumentSettings(exam);return `<footer class="exam-document-footer"><span>${esc(d.footer_left)}</span><span>${esc(d.footer_center)}</span><span>${esc(d.footer_right)}</span></footer>`;}
function documentEditor(){const d=examDocumentSettings(editor);return `<section class="panel document-editor"><h2>Encabezado y pie de página</h2><p>El logo MESA y estos textos aparecen al presentar la evaluación y en cada página del PDF. Publica los cambios para aplicarlos a nuevos participantes.</p>${field('Texto superior','document_top_text',d.top_text,'text','maxlength="180"')}<div class="form-grid">${field('Texto de revisión (arriba a la derecha)','document_revision_text',d.revision_text,'text','maxlength="120"')}${field('Pie izquierdo · fecha y revisión del formato','document_footer_left',d.footer_left,'text','required maxlength="240" placeholder="Fecha de Elaboración 09/07/2025, Rev. 01"')}</div><div class="form-grid">${field('Pie central · empresa','document_footer_center',d.footer_center,'text','maxlength="180"')}${field('Pie derecho · código del formato','document_footer_right',d.footer_right,'text','required maxlength="100" placeholder="FO-RH-14"')}</div><div class="document-preview-label">Vista previa</div><div id="document-preview" class="document-preview">${examDocumentHeader(editor)}${examDocumentFooter(editor)}</div></section>`;}
let managedUsers=[];
async function renderUsers(){
 if(!session.manage_users)throw Error('Solo el administrador puede gestionar usuarios.');
 managedUsers=await api('/admin/users');
 app.innerHTML=adminLayout(`<div class="page-title"><div><span class="eyebrow">ACCESO AL PANEL</span><h1 style="margin-top:8px">Usuarios de capacitación</h1><p>Los encargados pueden administrar exámenes, resultados y dashboards. Solo el administrador gestiona cuentas.</p></div><button class="primary" data-action="new-user">${icon('plus',16)} Crear usuario</button></div><section class="panel"><div class="table-wrap"><table><thead><tr><th>Usuario</th><th>Nombre</th><th>Acceso</th><th>Estado</th><th></th></tr></thead><tbody>${managedUsers.map(u=>`<tr><td><strong>${esc(u.username)}</strong></td><td>${esc(u.full_name||'—')}</td><td>${u.role==='administrator'?'Administrador':'Encargado de capacitación'}</td><td><span class="tag ${u.active?'teal':'amber'}">${u.active?'Activo':'Inactivo'}</span></td><td><button class="quiet small" data-action="edit-user" data-id="${u.id}">Editar</button></td></tr>`).join('')}</tbody></table></div></section>`,'users');
}
function userDialog(user){
 dialog.innerHTML=`<h2>${user?'Editar usuario':'Crear encargado de capacitación'}</h2><div id="user-form-error"></div><form id="user-form"><input type="hidden" name="id" value="${user?.id||''}">${user?`<p>Usuario: <b>${esc(user.username)}</b></p>`:field('Nombre de usuario','username','','text','required minlength="3" maxlength="80" autocomplete="off"')}${field('Nombre completo','full_name',user?.full_name||'','text','maxlength="150"')}${field(user?'Nueva contraseña (opcional)':'Contraseña (mínimo 10 caracteres)','password','','password',`${user?'':'required'} minlength="10" autocomplete="new-password"`)}${user?`<label class="checkline"><input type="checkbox" name="active" ${user.active?'checked':''} ${user.role==='administrator'?'disabled':''}>Acceso activo</label>`:''}<p>${user?.role==='administrator'?'Administrador con gestión de usuarios.':'Tendrá las mismas funciones de capacitación, excepto la gestión de usuarios.'}</p><div class="actions"><button type="button" data-action="close-dialog">Cancelar</button><button class="primary">${user?'Guardar cambios':'Crear usuario'}</button></div></form>`;dialog.showModal();
}
const statusTag=r=>`<span class="tag ${r.status==='pending_review'?'amber':r.summary?.passed?'teal':'red'}">${r.status==='pending_review'?'Por revisar':r.summary?.passed?'Aprobado':'No aprobado'}</span>`;
async function route(){const generation=++routeGeneration;clearTimeout(autosaveTimer);current=null;const parts=(location.hash.slice(1)||'inicio').split('/');const [page,id]=parts;app.innerHTML='<div class="loading">Cargando…</div>';try{
 if(page==='inicio'){catalog=await api('/exams');if(generation!==routeGeneration)return;renderHome()}
 else if(page==='exam'){const data=await api('/exams/'+id);if(generation!==routeGeneration)return;current=data;renderIntro()}
 else if(page==='attempt'||page==='done'){const data=await api('/attempts/'+id);if(generation!==routeGeneration)return;current={...data,token:id};if(data.status!=='started')renderDone();else renderAttempt()}
 else {session=await api('/session');if(generation!==routeGeneration)return;if(!session.authenticated){renderLogin();return}if(!adminCatalog.length)adminCatalog=await api('/admin/exams');if(page==='dashboard')await renderDashboard();else if(page==='exams')await renderExamList();else if(page==='users')await renderUsers();else if(page==='edit')await renderEditor(id);else if(page==='review')await renderReview(id);else await renderResults()}
 window.scrollTo(0,0);
 }catch(e){app.innerHTML=publicLayout(`<div class="panel narrow"><h1>No pudimos abrir esta página</h1><p>${esc(e.message)}</p><a class="button" href="#inicio">Volver al portal</a></div>`)}}
function renderHome(){app.innerHTML=publicLayout(`<section class="hero"><div><span class="eyebrow">TU SIGUIENTE PASO COMIENZA AQUÍ</span><h1>Aprende, demuestra<br>y sigue creciendo.</h1><p>Un espacio para evaluar lo que sabes y acompañar tu desarrollo en MESA. Elige tu evaluación y responde a tu ritmo.</p><div class="hero-meta"><span>${icon('check',14)} Para empleados y postulantes</span><span>${icon('file',14)} ${catalog.length} evaluaciones disponibles</span></div></div><div class="hero-illustration" aria-hidden="true"><div class="paper"><b>✓</b><i></i><i></i><i></i><i></i></div><div class="orb">✓</div></div></section><div class="section-title"><div><h2>Elige tu evaluación</h2><p>Encuentra el examen indicado por tu responsable de capacitación.</p></div><input id="catalog-search" class="control search" type="search" placeholder="Buscar una evaluación…" aria-label="Buscar evaluaciones"></div><div class="grid" id="exam-grid">${examCards(catalog)}</div><div class="notice">${icon('lock',15)} Tus respuestas se guardan para que el equipo de capacitación pueda revisar tus resultados.</div>`)}
function examCards(items){return items.length?items.map((e,i)=>`<article class="exam-card"><div class="card-top"><div class="icon-tile">${icon(i%2?'file':'book',23)}</div><span class="tag">${esc(e.category||'Capacitación')}</span></div><h3>${esc(e.title)}</h3><p>${esc(e.description||'Demuestra lo aprendido en tu capacitación.')}</p><div class="card-bottom"><small>${icon('file',13)} ${e.questions} preguntas</small><a href="#exam/${e.id}">Comenzar ${icon('arrow',15)}</a></div></article>`).join(''):'<div class="empty">No hay evaluaciones disponibles con esta búsqueda.</div>'}
function renderIntro(){const e=current.exam;const resume=sessionStorage.getItem('training-attempt-'+e.id);app.innerHTML=publicLayout(`<div class="narrow"><a class="back" href="#inicio">${icon('back',15)} Todas las evaluaciones</a><section class="panel exam-intro">${examDocumentHeader(e,'h1')}<span class="tag teal">${esc(e.category||'Capacitación')}</span><p>${esc(e.description)}</p><div class="exam-facts"><span>${icon('file',16)} ${e.questions.length} preguntas</span><span>${icon('clock',16)} ${esc(e.duration||'Sin límite')} min sugeridos</span><span>${icon('users',16)} Empleados y postulantes</span></div><small>${esc(e.instructions||'Lee cada pregunta y responde con base en tu capacitación.')}</small>${e.source_file?`<div class="source-label">${esc(e.source_file)} · ${esc(e.revision||'Documento de referencia')}</div>`:''}</section><form id="identity" class="panel"><h2>Antes de comenzar</h2><p>Escribe tus datos para identificar tu evaluación.</p><div id="form-error"></div>${field('Nombre completo','name','','text','required minlength="3" maxlength="150" autocomplete="name"')}<div class="form-grid"><label class="field">Soy<select name="type" id="participant-type"><option value="employee">Empleado de MESA</option><option value="applicant">Postulante</option></select></label>${field('Número de nómina','payroll','','text','required maxlength="50" id="payroll"')}</div>${field('Departamento o puesto al que postulas','department','','text','maxlength="150"')}<label class="checkline"><input type="checkbox" required>Confirmo que mis datos son correctos y que responderé esta evaluación de forma individual.</label><div class="actions">${resume?`<a class="button" href="#attempt/${esc(resume)}">Continuar evaluación anterior</a>`:''}<button class="primary">Comenzar evaluación ${icon('arrow',16)}</button></div></form>${examDocumentFooter(e)}</div>`)}
function renderLogin(){app.innerHTML=publicLayout(`<div class="login-layout"><section class="panel login-card"><div class="icon-tile">${icon('lock',22)}</div><h1>Espacio de capacitación</h1><p>Accede para crear evaluaciones, revisar respuestas y consultar resultados.</p><div id="form-error"></div><form id="login">${field('Usuario','username','','text','required autocomplete="username"')}${field('Contraseña','password','','password','required autocomplete="current-password"')}<button class="primary">Entrar al panel ${icon('arrow',16)}</button></form></section></div>`)}
function questionImage(q){return q.image?`<img class="question-image" src="${esc(q.image)}" alt="${esc(q.image_alt||'Figura de referencia para esta pregunta')}">`:''}
const reviewLabels={correct:'Correcta',incorrect:'Incorrecta',partial:'Parcialmente correcta',pending:'Pendiente de revisión'};
function reviewBadge(review){const state=review?.status||'pending';return `<span class="answer-status ${state}">${state==='correct'?'✓':state==='incorrect'?'✕':state==='partial'?'◐':'◷'} ${reviewLabels[state]}</span>`;}
function reviewAnswer(q,value,review){
 const r=review||{status:'pending',has_key:false,items:[]};
 const picture=questionImage(q);
 const format=v=>Array.isArray(v)?v.join(', '):String(v??'Sin respuesta');
 let body='';
 if(r.has_key && ['matching','table'].includes(q.type)){
  body=`<p class="review-breakdown"><b>${r.matched} de ${r.total}</b> ${q.type==='matching'?'relaciones':'respuestas'} correctas según la clave.</p><div class="table-wrap"><table class="answer-review-table"><thead><tr><th>${q.type==='matching'?'Concepto':'Referencia / campo'}</th><th>Respuesta registrada</th><th>Resultado</th><th>Respuesta correcta</th></tr></thead><tbody>${r.items.map(item=>`<tr class="${item.correct?'answer-correct':'answer-incorrect'}"><th scope="row">${esc(item.label)}</th><td>${esc(item.answer||'Sin respuesta')}</td><td><span class="answer-status ${item.correct?'correct':'incorrect'}">${item.correct?'✓ Correcta':'✕ Incorrecta'}</span></td><td>${esc(item.correct_answer)}</td></tr>`).join('')}</tbody></table></div>`;
 }else if(r.has_key && ['single','multiple','boolean'].includes(q.type)){
  body=`<div class="review-options">${r.items.map(item=>{const state=item.selected&&!item.correct?'incorrect':item.correct?'correct':'neutral';const label=item.selected?(item.correct?'Tu respuesta · Correcta':'Tu respuesta · Incorrecta'):item.correct?(q.type==='multiple'?'Faltó seleccionarla · Respuesta correcta':'Respuesta correcta'):'';return `<div class="review-option ${state}"><span class="review-choice-mark" aria-hidden="true">${item.selected?'☑':'☐'}</span><div>${esc(item.label)}${label?`<small>${esc(label)}</small>`:''}</div></div>`;}).join('')}</div>`;
 }else if(q.type==='image_mark')body=markedImage(q,value||[],true);
 else if(['matching','table','single','multiple','boolean'].includes(q.type))body=answerControl(q,value,true);
 else body=`<div class="response ${r.status}">${esc(value??'Sin respuesta')||'Sin respuesta'}</div>`;
 const solution=r.has_key && !['matching','table','single','multiple','boolean'].includes(q.type) && r.status!=='correct'?`<div class="review-solution"><b>Respuesta correcta:</b> ${esc(format(r.correct_answer))}${q.type==='number'&&q.tolerance?`<small>Tolerancia admitida: ±${esc(q.tolerance)}</small>`:''}</div>`:'';
 return (q.type==='image_mark'?'':picture)+body+solution+(!r.has_key?'<p class="review-no-key">Sin clave configurada en esta versión. La puntuación se revisa manualmente; no es posible identificar qué filas u opciones son correctas.</p>':'');
}
function answerControl(q,v,readonly=false){const attr=`data-q="${q.id}"`;if(q.type==='image_mark')return markedImage(q,v||[],readonly);const picture=questionImage(q);
 if(['single','boolean','multiple'].includes(q.type)){const opts=q.type==='boolean'?['Verdadero','Falso']:q.options;return picture+opts.map(o=>`<label class="option"><input type="${q.type==='multiple'?'checkbox':'radio'}" name="answer-${q.id}" ${attr} value="${esc(o)}" ${(q.type==='multiple'?(v||[]).includes(o):v===o)?'checked':''} ${readonly?'disabled':''}><span>${esc(o)}</span></label>`).join('')}
 if(q.type==='matching')return picture+`<div class="table-wrap"><table class="answer-table"><thead><tr><th>Concepto</th><th>Tu respuesta</th></tr></thead><tbody>${q.rows.map(row=>`<tr><td>${esc(row)}</td><td><select ${attr} data-field="${esc(row)}" ${readonly?'disabled':''}><option value="">Selecciona…</option>${q.options.map(o=>`<option ${v?.[row]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`;
 if(q.type==='table')return picture+`<div class="table-wrap"><table class="answer-table"><thead><tr><th>Referencia</th>${q.columns.map(col=>`<th>${esc(col)}</th>`).join('')}</tr></thead><tbody>${q.rows.map((row,i)=>`<tr><td>${esc(row)}</td>${q.columns.map((col,j)=>`<td><input ${attr} data-field="${i}:${j}" value="${esc(v?.[`${i}:${j}`]||'')}" aria-label="${esc(row+' · '+col)}" ${readonly?'readonly':''}></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 return picture+`<label class="field"><span class="sr-label">Tu respuesta</span>${q.type==='long_text'?`<textarea ${attr} rows="4" maxlength="20000" ${readonly?'readonly':''}>${esc(v||'')}</textarea>`:`<input ${attr} type="${q.type==='number'?'number':'text'}" step="any" value="${esc(v??'')}" maxlength="20000" ${readonly?'readonly':''}>`}</label>`}
function markedImage(q,marks,readonly){return `<div class="mark-area" ${readonly?'':`data-mark="${q.id}"`}><img src="${esc(q.image)}" alt="${esc(q.image_alt||q.prompt)}">${marks.map((p,i)=>`<span class="mark-dot" style="left:${p.x*100}%;top:${p.y*100}%">${i+1}</span>`).join('')}</div><div class="mark-labels" data-labels="${q.id}">${marks.map((p,i)=>p.label?`<small>${i+1}. ${esc(p.label)}</small><br>`:'').join('')}</div>${readonly?'':`<small>Haz clic sobre la imagen para marcar tu respuesta. También puedes usar coordenadas porcentuales.</small><label class="field">Etiqueta de la marca ${q.mark_labels?'(obligatoria)':'(opcional)'}<input data-mark-label="${q.id}" maxlength="200" placeholder="Nombre o nota de la marca"></label><div class="mark-controls"><label class="field">Horizontal %<input type="number" min="0" max="100" data-x="${q.id}" aria-label="Posición horizontal"></label><label class="field">Vertical %<input type="number" min="0" max="100" data-y="${q.id}" aria-label="Posición vertical"></label><button type="button" class="small" data-action="add-mark" data-id="${q.id}">Añadir marca</button><button type="button" class="quiet small" data-action="clear-marks" data-id="${q.id}">Borrar marcas (${marks.length})</button></div>`}`}
function renderAttempt(){const e=current.exam;app.innerHTML=publicLayout(`<div class="narrow">${examDocumentHeader(e,'h1')}<div class="attempt-head"><div class="progress-top"><b>${esc(e.title)}</b><span id="attempt-progress"></span></div><div class="progress-track"><i id="progress-line"></i></div><small id="save-status" class="saving">Tus respuestas se guardan mientras respondes.</small></div><form id="attempt-form"><div id="form-error"></div>${e.questions.map((q,i)=>`<section class="panel question" id="question-${q.id}">${q.section?`<div class="section">${esc(q.section)}</div>`:''}<div class="question-number"><span>PREGUNTA ${i+1} <span class="muted">${q.required===false?'· Opcional':'· Obligatoria'}</span></span><span class="muted">${q.points} ${q.points===1?'punto':'puntos'}</span></div><h3>${esc(q.prompt)}</h3>${q.help?`<p>${esc(q.help)}</p>`:''}${answerControl(q,current.answers[q.id])}</section>`).join('')}<div class="panel"><p>Al enviar, tus respuestas quedarán registradas para su evaluación.</p><button class="primary">Revisar y enviar ${icon('arrow',16)}</button></div></form>${examDocumentFooter(e)}</div>`);updateProgress()}
function collected(){const ans={...current.answers};for(const q of current.exam.questions){if(q.type==='image_mark')continue;const nodes=[...document.querySelectorAll(`[data-q="${q.id}"]`)];if(['single','boolean'].includes(q.type))ans[q.id]=nodes.find(n=>n.checked)?.value||'';else if(q.type==='multiple')ans[q.id]=nodes.filter(n=>n.checked).map(n=>n.value);else if(['matching','table'].includes(q.type))ans[q.id]=Object.fromEntries(nodes.map(n=>[n.dataset.field,n.value]));else ans[q.id]=nodes[0]?.value||''}return ans}
function isAnswered(q,v){if(q.type==='matching'||q.type==='table'){const expected=q.rows.length*(q.type==='table'?q.columns.length:1);return v&&Object.keys(v).length===expected&&Object.values(v).every(x=>String(x).trim())}return Array.isArray(v)?v.length>0:v!==undefined&&v!==null&&String(v).trim()!==''}
function updateProgress(){if(!current?.exam)return;const answered=current.exam.questions.filter(q=>isAnswered(q,current.answers[q.id])).length;const p=document.querySelector('#attempt-progress');if(p)p.textContent=`${answered} de ${current.exam.questions.length} respondidas`;const line=document.querySelector('#progress-line');if(line)line.style.width=(answered/current.exam.questions.length*100)+'%'}
function scheduleSave(){clearTimeout(autosaveTimer);const token=current.token;const answers=current.answers;autosaveTimer=setTimeout(async()=>{const s=document.querySelector('#save-status');try{if(s)s.textContent='Guardando…';await api('/attempts/'+token,'PUT',{answers});if(s)s.textContent='Respuestas guardadas.'}catch(e){if(s)s.textContent='No se guardó el último cambio. Reintentaremos al responder o enviar.'}},650)}
function renderDone(){sessionStorage.removeItem('training-attempt-'+current.exam_id);const s=current.summary;app.innerHTML=publicLayout(`<section class="panel narrow done"><div class="done-icon">${icon('check',38)}</div><span class="eyebrow">EVALUACIÓN REGISTRADA</span><h1 style="margin-top:15px">Gracias, ${esc(current.participant.name.split(' ')[0])}.</h1><p>Recibimos tus respuestas de <b>${esc(current.exam_title)}</b>.</p>${current.status==='graded'?`<div class="score">${pct(s.score)}</div><span class="tag ${s.passed?'teal':'amber'}">${s.passed?'Aprobado':'No aprobado'}</span>`:'<div class="notice">Tu evaluación está pendiente de revisión por el equipo de capacitación. La calificación aparecerá aquí cuando finalicen la revisión.</div>'}<p style="margin-top:24px">Folio <b>MESA-${String(current.id).padStart(5,'0')}</b> · ${dt(current.submitted_at)}</p><small>Conserva esta página para consultar tu resultado.</small><div class="actions" style="justify-content:center"><a class="button primary" href="#inicio">Volver a las evaluaciones</a><button data-action="refresh">Actualizar resultado</button></div></section>`)}
let activeQuery='';
function filtersHTML(){return `<form id="admin-filters" class="filters">${field('Número de nómina','payroll','','search','placeholder="Buscar nómina exacta" autocomplete="off"')}<label class="field">Evaluación<select name="exam"><option value="">Todas las evaluaciones</option>${adminCatalog.map(e=>`<option value="${e.id}">${esc(e.title)}</option>`).join('')}</select></label><label class="field">Participante<select name="type"><option value="">Todos</option><option value="employee">Empleados</option><option value="applicant">Postulantes</option></select></label>${field('Desde','from','','date')}${field('Hasta','to','','date')}<label class="field">Historial<select name="history"><option value="active">Vigentes</option><option value="archived">Eliminados del historial</option></select></label><button class="small">Aplicar filtros</button><button type="button" class="quiet small" data-action="clear-filters">Limpiar</button></form>`}
function resultTable(rows){return rows.length?`<div class="table-wrap"><table><thead><tr><th>Nómina / participante</th><th>Evaluación</th><th>Intentos</th><th>Fecha</th><th>Calificación</th><th>Estado</th><th>Acciones</th></tr></thead><tbody>${rows.map(r=>`<tr><td><strong>${esc(r.participant.payroll||'Sin nómina')}</strong>${esc(r.participant.name)}<br><small>${r.participant.type==='employee'?'Empleado':'Postulante'}</small></td><td>${esc(r.exam_title)}</td><td>${r.exam_attempts||1}<small> del mismo examen</small></td><td>${dt(r.submitted_at)}</td><td><b>${pct(r.summary?.score)}</b></td><td>${statusTag(r)}${r.archived?'<br><span class="tag amber">Eliminado del historial</span>':''}</td><td class="result-actions-cell"><div class="result-actions" role="group" aria-label="Acciones de la evaluaci?n ${r.id}"><a class="button small primary result-action" href="#review/${r.id}">${icon('file',14)} ${r.status==='pending_review'?'Revisar':'Ver detalle'} →</a><button type="button" class="small result-action" data-action="download-pdf" data-kind="results" data-id="${r.id}" data-filename="evaluacion-MESA-${String(r.id).padStart(5,'0')}-${esc(r.participant.payroll||'postulante')}.pdf">${icon('download',14)} Descargar PDF</button><button type="button" class="small result-action ${r.archived?'':'danger'}" data-action="attempt-history" data-id="${r.id}" data-archived="${r.archived?'false':'true'}">${icon(r.archived?'back':'trash',14)} ${r.archived?'Restaurar':'Eliminar del historial'}</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">'+icon('file',30)+'<h3>Sin resultados para estos filtros</h3>Prueba otra nómina o limpia los filtros.</div>'}
function payrollTable(people){return `<section class="panel"><div class="panel-title"><div><h2>Seguimiento por número de nómina</h2><small>Intentos y exámenes dentro de los filtros seleccionados</small></div></div>${people?.length?`<div class="table-wrap"><table><thead><tr><th>Nómina</th><th>Empleado</th><th>Total de intentos</th><th>Exámenes realizados</th><th>Promedio</th><th>Última evaluación</th><th></th></tr></thead><tbody>${people.map(p=>`<tr><td><b>${esc(p.payroll)}</b></td><td>${esc(p.name)}</td><td>${p.attempts}</td><td>${p.exams.map(e=>`${esc(e.title)} · <b>${e.attempts}</b> ${e.attempts===1?'vez':'veces'}`).join('<br>')}</td><td>${pct(p.average)}</td><td>${dt(p.latest)}</td><td><button class="quiet small" data-action="payroll-results" data-payroll="${esc(p.payroll)}">Ver historial →</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No hay empleados con evaluaciones para estos filtros.</div>'}</section>`}
function lineChart(days){const entries=Object.entries(days).sort();if(!entries.length)return '<div class="chart-empty">La actividad comenzará con la primera evaluación.<span>Las respuestas reales se reflejarán en esta gráfica.</span></div>';const max=Math.max(...entries.map(x=>x[1]),1),width=560,height=180;const points=entries.map(([d,v],i)=>[35+i*(width-70)/Math.max(entries.length-1,1),height-32-(v/max)*(height-55)]);return `<svg class="trend" viewBox="0 0 ${width} ${height}" role="img" aria-label="Evaluaciones recibidas por día">${[0,.5,1].map(v=>`<line x1="35" y1="${height-32-v*(height-55)}" x2="540" y2="${height-32-v*(height-55)}" stroke="#e8eff2"/><text x="10" y="${height-28-v*(height-55)}">${Math.round(max*v)}</text>`).join('')}<polyline points="${points.map(p=>p.join(',')).join(' ')}" fill="none" stroke="#148d91" stroke-width="2.5"/>${points.map((p,i)=>`<circle cx="${p[0]}" cy="${p[1]}" r="4" fill="#148d91"/><text x="${p[0]}" y="174" text-anchor="middle">${esc(entries[i][0].slice(5))}</text>`).join('')}</svg>`}
async function renderDashboard(query=''){activeQuery=query;const d=await api('/admin/dashboard'+query);app.innerHTML=adminLayout(`<div class="page-title"><div><span class="eyebrow">VISTA GENERAL</span><h1 style="margin-top:8px">El progreso de tu equipo, en un lugar.</h1><p>Consulta la participación y los resultados de capacitación.</p></div><a class="button primary" href="#edit/new">${icon('plus',15)} Crear examen</a></div>${filtersHTML()}<div id="dashboard-data">${dashboardBody(d)}${payrollTable(d.by_payroll)}</div>`);restoreFilters(query)}
function dashboardBody(d){return `<div class="metrics">${[['Evaluaciones recibidas',d.total,'Enviadas por empleados y postulantes','file'],['Calificación promedio',pct(d.average),`${d.graded} evaluaciones calificadas`,'chart'],['Tasa de aprobación',pct(d.pass_rate),'Sobre evaluaciones calificadas','check'],['Pendientes de revisar',d.pending,'Requieren revisión de capacitación','clock']].map(([label,value,hint,ic])=>`<article class="metric"><div>${label}<span class="icon-tile">${icon(ic,16)}</span></div><strong>${value}</strong><small>${hint}</small></article>`).join('')}</div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><div><h2>Participación a través del tiempo</h2><small>Evaluaciones recibidas por día</small></div><span class="tag">${d.total} respuestas</span></div>${lineChart(d.by_day)}</section><section class="panel"><div class="panel-title"><div><h2>¿Quiénes participan?</h2><small>Distribución por tipo de participante</small></div></div><div class="participant-chart"><div class="donut" style="background:conic-gradient(#138d8e 0 ${d.total?d.employees/d.total*100:0}%,#a3c4e4 ${d.total?d.employees/d.total*100:0}% 100%)"><strong>${d.total}</strong><small>participantes</small></div><div class="legend"><div><i class="dot"></i>Empleados <strong>${d.employees}</strong></div><div><i class="dot" style="background:#a3c4e4"></i>Postulantes <strong>${d.applicants}</strong></div></div></div></section></div><div class="dashboard-grid"><section class="panel"><div class="panel-title"><h2>Últimas evaluaciones</h2><a href="#results">Ver todas →</a></div>${resultTable(d.recent)}</section><section class="panel"><div class="panel-title"><div><h2>Resultados por evaluación</h2><small>Promedio de respuestas calificadas</small></div></div>${d.by_exam.length?`<div class="bars">${d.by_exam.map(e=>`<div><div class="bar-label"><span>${esc(e.title)}</span><b>${pct(e.average)}</b></div><div class="bar-line"><i style="width:${e.average||0}%"></i></div><small>${e.count} evaluaciones recibidas</small></div>`).join('')}</div>`:'<div class="chart-empty">Todavía no hay calificaciones por comparar.</div>'}${d.pending?`<div class="review-banner"><div><b>${d.pending} evaluaciones por revisar</b>Completa su revisión para calcular resultados.</div><a href="#results">Revisar →</a></div>`:''}</section></div>`}
function restoreFilters(query){const params=new URLSearchParams(query.replace(/^\?/,''));const f=document.querySelector('#admin-filters');if(f)for(const [k,v]of params)if(f.elements[k])f.elements[k].value=v}
async function renderResults(query=''){activeQuery=query;const rows=await api('/admin/results'+query);app.innerHTML=adminLayout(`<div class="page-title"><div><span class="eyebrow">RESPUESTAS Y SEGUIMIENTO</span><h1 style="margin-top:8px">Resultados de evaluación</h1><p>Revisa respuestas y completa las calificaciones pendientes.</p></div><a id="export-results" class="button" href="/api/admin/export${esc(query)}">${icon('download',15)} Exportar CSV</a></div>${filtersHTML()}<section class="panel">${resultTable(rows)}</section>`,'results');restoreFilters(query)}
async function renderExamList(){adminCatalog=await api('/admin/exams');app.innerHTML=adminLayout(`<div class="page-title"><div><span class="eyebrow">BIBLIOTECA DE CAPACITACIÓN</span><h1 style="margin-top:8px">Tus evaluaciones</h1><p>Crea, actualiza y comparte exámenes con tu equipo.</p></div><a class="button primary" href="#edit/new">${icon('plus',16)} Crear examen</a></div><div class="grid">${adminCatalog.map(e=>`<article class="exam-card"><div class="card-top"><div class="icon-tile">${icon('book',22)}</div><span class="tag ${e.archived?'amber':e.published_version?'teal':''}">${e.archived?'Archivado':e.published_version?'Publicado · v'+e.published_version:'Borrador'}</span></div><h3>${esc(e.title)}</h3><p>${e.questions} preguntas · ${esc(e.category)}<br>${e.manual} preguntas de revisión manual</p><div class="card-bottom"><a href="#edit/${e.id}">${icon('edit',14)} Editar examen</a><button class="quiet small" data-action="share" data-id="${e.id}">Compartir</button></div><button type="button" class="quiet small" data-action="download-pdf" data-kind="exams" data-id="${e.id}" data-filename="evaluacion-${e.id}.pdf">${icon('download',14)} Descargar PDF</button><button class="quiet small" data-action="archive" data-id="${e.id}">${e.archived?'Volver a mostrar':'Archivar'}</button></article>`).join('')}</div>`,'exams')}
const newQuestion=type=>({id:'q'+crypto.randomUUID().replaceAll('-','').slice(0,12),type,prompt:'',points:1,required:true,section:'',options:['Opción 1','Opción 2'],rows:['Referencia 1','Referencia 2'],columns:['Respuesta'],correct:null});
async function renderEditor(id){editorId=id==='new'?null:id;if(editorId){const d=await api('/admin/exams/'+editorId);editor=d.exam;editorVersion=d.published_version}else{editor={title:'',description:'',category:'Capacitación',duration:20,pass_score:80,instructions:'Lee cada pregunta y selecciona o escribe tu respuesta.',questions:[newQuestion('single')]};editorVersion=null}paintEditor()}
function keyInputs(q){if(q.correct===null||q.correct===undefined)return '';const keyAttr=`data-key="${q.id}"`;
 if(['single','boolean'].includes(q.type))return `<label class="field">Respuesta correcta<select ${keyAttr}><option value="">Selecciona…</option>${(q.type==='boolean'?['Verdadero','Falso']:q.options).map(o=>`<option ${q.correct===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`;
 if(q.type==='multiple')return q.options.map(o=>`<label class="checkline"><input type="checkbox" ${keyAttr} value="${esc(o)}" ${(q.correct||[]).includes(o)?'checked':''}>${esc(o)}</label>`).join('');
 if(q.type==='matching')return q.rows.map(row=>`<label class="field">${esc(row)}<select ${keyAttr} data-field="${esc(row)}"><option value="">Selecciona…</option>${q.options.map(o=>`<option ${q.correct?.[row]===o?'selected':''}>${esc(o)}</option>`).join('')}</select></label>`).join('');
 if(q.type==='table')return `<div class="table-wrap"><table class="answer-table"><thead><tr><th>Referencia</th>${q.columns.map(x=>`<th>${esc(x)}</th>`).join('')}</tr></thead><tbody>${q.rows.map((row,i)=>`<tr><td>${esc(row)}</td>${q.columns.map((col,j)=>`<td><input ${keyAttr} data-field="${i}:${j}" value="${esc(q.correct?.[`${i}:${j}`]||'')}" aria-label="${esc(row+' '+col)}"></td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
 return `<label class="field">Respuesta correcta<input ${keyAttr} value="${esc(q.correct??'')}" type="${q.type==='number'?'number':'text'}" step="any"></label>${q.type==='number'?`<label class="field">Tolerancia numérica<input type="number" step="any" min="0" data-question="${q.id}" data-prop="tolerance" value="${esc(q.tolerance||0)}"></label>`:''}`}
function paintEditor(){app.innerHTML=adminLayout(`<a class="back" href="#exams">${icon('back',15)} Biblioteca de exámenes</a><div class="page-title"><div><h1>${editorId?'Editar evaluación':'Crear una evaluación'}</h1><p>${editorVersion?'Versión publicada '+editorVersion+'. Los cambios se guardan como borrador hasta publicar.':'Configura tus preguntas y publica cuando esté listo.'}</p></div><span class="tag">${editor.questions.length} preguntas</span></div><div id="form-error"></div><form id="editor-form"><div class="editor-meta"><section class="panel"><h2>Información de la evaluación</h2>${field('Título','title',editor.title,'text','required maxlength="180"')}<label class="field">Descripción<textarea name="description">${esc(editor.description)}</textarea></label><div class="form-grid three">${field('Categoría','category',editor.category)}${field('Duración sugerida (min)','duration',editor.duration,'number','min="1" max="300"')}${field('Mínimo aprobatorio (%)','pass_score',editor.pass_score,'number','min="0" max="100" required')}</div><label class="field">Instrucciones<textarea name="instructions">${esc(editor.instructions)}</textarea></label>${editor.source_file?`<div class="source-label">Fuente: ${esc(editor.source_file)} · ${esc(editor.revision)}</div>`:''}</section><aside class="panel editor-side"><div class="icon-tile">${icon('file',22)}</div><h3 style="margin-top:18px">Una evaluación a tu medida</h3><p>Combina preguntas abiertas, opciones, tablas e imágenes.</p><p>Activa una clave para calificar automáticamente. Las preguntas sin clave se envían a revisión manual.</p><div class="notice">Las respuestas ya enviadas conservan la versión del examen con la que se realizaron.</div></aside></div>${documentEditor()}${editor.questions.map((q,i)=>`<section class="panel editor-question" data-editor-q="${q.id}"><div class="question-top"><b>Pregunta ${i+1}</b><div class="question-tools"><button type="button" class="quiet small" data-action="move-q" data-id="${q.id}" data-delta="-1" aria-label="Subir pregunta ${i+1}">↑</button><button type="button" class="quiet small" data-action="move-q" data-id="${q.id}" data-delta="1" aria-label="Bajar pregunta ${i+1}">↓</button><button type="button" class="quiet small danger" data-action="remove-q" data-id="${q.id}">Quitar</button></div></div><label class="field">Enunciado<textarea data-question="${q.id}" data-prop="prompt" required>${esc(q.prompt)}</textarea></label><div class="form-grid"><label class="field">Tipo de pregunta<select data-question="${q.id}" data-prop="type">${Object.entries(typeNames).map(([key,label])=>`<option value="${key}" ${q.type===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Puntos<input type="number" min="0.1" max="1000" step="0.1" value="${q.points}" data-question="${q.id}" data-prop="points" required></label><label class="checkline"><input type="checkbox" ${q.required!==false?'checked':''} data-question="${q.id}" data-prop="required">Obligatoria</label></div><label class="field">Sección (opcional)<input value="${esc(q.section||'')}" data-question="${q.id}" data-prop="section"></label>${['single','multiple','matching'].includes(q.type)?`<label class="field">Opciones · una por línea<textarea data-question="${q.id}" data-prop="options" rows="4">${esc((q.options||[]).join('\n'))}</textarea></label>`:''}${['matching','table'].includes(q.type)?`<div class="form-grid"><label class="field">Filas · una por línea<textarea data-question="${q.id}" data-prop="rows">${esc((q.rows||[]).join('\n'))}</textarea></label>${q.type==='table'?`<label class="field">Columnas de respuesta · una por línea<textarea data-question="${q.id}" data-prop="columns">${esc((q.columns||[]).join('\n'))}</textarea></label>`:''}</div>`:''}${q.image?questionImage(q)+`<button type="button" class="quiet small" data-action="remove-image" data-id="${q.id}">Quitar imagen</button>`:''}<label class="field">Imagen de apoyo (PNG o JPEG, hasta 5 MB)<input type="file" accept="image/png,image/jpeg" data-upload="${q.id}"></label><div class="key-box">${q.type!=='image_mark'?`<label class="checkline"><input type="checkbox" data-key-toggle="${q.id}" ${q.correct!==null&&q.correct!==undefined?'checked':''}>Calificar automáticamente con una clave</label>${keyInputs(q)}`:'<p>Las marcas sobre imágenes requieren revisión manual.</p>'}<label class="field">Criterio de revisión (solo visible para capacitación)<textarea data-question="${q.id}" data-prop="rubric">${esc(q.rubric||'')}</textarea></label></div></section>`).join('')}<section class="add-question"><h3>Añade una pregunta</h3><div class="type-options">${Object.entries(typeNames).map(([type,label])=>`<button type="button" data-action="add-q" data-type="${type}">${icon('plus',13)}${label}</button>`).join('')}</div></section><div class="editor-toolbar"><small>${editor.questions.length} preguntas · ${editor.questions.reduce((a,q)=>a+Number(q.points||0),0)} puntos</small><div class="actions"><button value="draft">Guardar borrador</button><button class="primary" value="publish">Guardar y publicar ${icon('arrow',15)}</button></div></div></form>`,'exams')}
function gatherEditor(){const f=document.querySelector('#editor-form');if(!f)return;for(const key of ['title','description','category','instructions'])editor[key]=f.elements[key].value;editor.document=Object.fromEntries(['top_text','revision_text','footer_left','footer_center','footer_right'].map(key=>[key,f.elements['document_'+key].value]));editor.duration=Number(f.elements.duration.value);editor.pass_score=Number(f.elements.pass_score.value);for(const el of f.querySelectorAll('[data-question]')){const q=editor.questions.find(q=>q.id===el.dataset.question);const prop=el.dataset.prop;q[prop]=['options','rows','columns'].includes(prop)?el.value.split('\n').map(x=>x.trim()).filter(Boolean):['points','tolerance'].includes(prop)?Number(el.value):prop==='required'?el.checked:el.value}for(const q of editor.questions){if(q.correct===null||q.correct===undefined)continue;const nodes=[...f.querySelectorAll(`[data-key="${q.id}"]`)];if(q.type==='multiple')q.correct=nodes.filter(n=>n.checked).map(n=>n.value);else if(['matching','table'].includes(q.type))q.correct=Object.fromEntries(nodes.map(n=>[n.dataset.field,n.value]));else q.correct=nodes[0]?.value??null}}
async function renderReview(id){const r=await api('/admin/results/'+id);current=r;app.innerHTML=adminLayout(`${examDocumentHeader(r.exam)}<a class="back" href="#results">${icon('back',15)} Todos los resultados</a><div class="page-title"><div><h1>${esc(r.participant.name)}</h1><p>${esc(r.exam_title)} · Versión ${r.version} · Folio MESA-${String(r.id).padStart(5,'0')}</p></div><div class="actions">${statusTag(r)}<button type="button" data-action="download-pdf" data-kind="results" data-id="${r.id}" data-filename="evaluacion-MESA-${String(r.id).padStart(5,'0')}-${esc(r.participant.payroll||'postulante')}.pdf" title="Incluye la ultima revision guardada">${icon('download',15)} Descargar PDF</button></div></div><div class="panel"><div class="review-meta"><span>${r.participant.type==='employee'?'Empleado · '+esc(r.participant.payroll):'Postulante'}</span><span>${esc(r.participant.department||'Sin departamento')}</span><span>Enviado: ${dt(r.submitted_at)}</span><span>${r.summary.pending} preguntas pendientes</span><b>Calificación: ${pct(r.summary.score)}</b></div></div><form id="review-form"><div id="form-error"></div>${r.exam.questions.map((q,i)=>`<section class="panel review-question review-${r.answer_review?.[q.id]?.status||'pending'}"><div><div class="question-number">PREGUNTA ${i+1} · ${typeNames[q.type]}</div><h3>${esc(q.prompt)}</h3>${reviewBadge(r.answer_review?.[q.id])}${reviewAnswer(q,r.answers[q.id],r.answer_review?.[q.id])}${q.rubric?`<div class="notice"><b>Criterio de revisión:</b> ${esc(q.rubric)}</div>`:''}</div><div class="grade"><label class="field">Puntos (máximo ${q.points})<input type="number" min="0" max="${q.points}" step="0.01" name="score-${q.id}" value="${r.grading[q.id]?.points??''}" placeholder="Pendiente"></label><label class="field">Observaciones<textarea name="feedback-${q.id}">${esc(r.grading[q.id]?.feedback||'')}</textarea></label><small>${r.grading[q.id]?.mode==='auto'?'Calificación automática':'Revisión manual'}</small></div></section>`).join('')}<div class="editor-toolbar"><small>Las preguntas sin puntos continúan pendientes.</small><div class="actions"><button type="button" data-action="print">Imprimir</button><button class="primary">Guardar revisión ${icon('check',16)}</button></div></div></form>${examDocumentFooter(r.exam)}`,'results')}
function confirmSubmit(){current.answers=collected();const missing=current.exam.questions.filter(q=>q.required!==false&&!isAnswered(q,current.answers[q.id]));document.querySelectorAll('.question').forEach(n=>n.classList.remove('invalid'));if(missing.length){for(const q of missing)document.querySelector('#question-'+q.id)?.classList.add('invalid');error(`Faltan ${missing.length} preguntas obligatorias. Completa las preguntas marcadas.`);return}dialog.innerHTML=`<h2>¿Enviar tu evaluación?</h2><p>Revisa que todas tus respuestas sean correctas. Después de enviar, el equipo de capacitación podrá revisarlas.</p><div class="actions"><button data-action="close-dialog">Seguir revisando</button><button class="primary" data-action="submit-final">Enviar evaluación</button></div>`;dialog.showModal()}
document.addEventListener('submit',async event=>{const f=event.target;const formId=f.getAttribute('id');if(!formId)return;event.preventDefault();const button=event.submitter;try{
 if(formId==='login'){const data=Object.fromEntries(new FormData(f));session=await api('/login','POST',data);location.hash='#dashboard';await route()}
 else if(formId==='identity'){const p=Object.fromEntries(new FormData(f));const r=await api('/attempts','POST',{exam_id:current.exam.id,participant:p});sessionStorage.setItem('training-attempt-'+current.exam.id,r.token);location.hash='#attempt/'+r.token}
 else if(formId==='attempt-form')confirmSubmit();
 else if(formId==='admin-filters'){const query='?'+new URLSearchParams(new FormData(f));if(location.hash.startsWith('#dashboard'))await renderDashboard(query);else await renderResults(query)}
 else if(formId==='editor-form'){gatherEditor();if(button)button.disabled=true;let id=editorId;if(id)await api('/admin/exams/'+id,'PUT',editor);else{id=(await api('/admin/exams','POST',editor)).id;editorId=id}if(button?.value==='publish'){const r=await api('/admin/exams/'+id+'/publish','POST',{});editorVersion=r.version;toast('Evaluación publicada · versión '+r.version)}else toast('Borrador guardado.');adminCatalog=await api('/admin/exams');history.replaceState(null,'','#edit/'+id);paintEditor()}
 else if(formId==='review-form'){const grading={};for(const q of current.exam.questions){const value=f.elements['score-'+q.id].value;if(value!=='')grading[q.id]={points:Number(value),feedback:f.elements['feedback-'+q.id].value}}await api('/admin/results/'+current.id,'POST',{grading});toast('Revisión guardada.');await renderReview(current.id)}
 else if(formId==='attempt-history-form'){const values=Object.fromEntries(new FormData(f));await api('/admin/results/'+values.attempt_id+'/history','POST',{archived:values.archived==='true',reason:values.reason});dialog.close();toast(values.archived==='true'?'Evaluación retirada del historial.':'Evaluación restaurada.');if(location.hash.startsWith('#dashboard'))await renderDashboard(activeQuery);else await renderResults(activeQuery)}
 else if(formId==='user-form'){const values=Object.fromEntries(new FormData(f));if(values.id){await api('/admin/users/'+values.id,'PUT',{full_name:values.full_name,active:f.elements.active.checked,password:values.password})}else{await api('/admin/users','POST',{username:values.username,full_name:values.full_name,password:values.password})}dialog.close();toast(values.id?'Usuario actualizado.':'Encargado de capacitación creado.');await renderUsers()}
 else if(formId==='password-form'){await api('/admin/password','POST',Object.fromEntries(new FormData(f)));dialog.close();toast('Contraseña actualizada.')}
 }catch(e){error(e.message)}finally{if(button)button.disabled=false}});
document.addEventListener('input',event=>{const el=event.target;if(el.name?.startsWith('document_') || (el.name==='title' && editor)){const f=document.querySelector('#editor-form');editor.document=Object.fromEntries(['top_text','revision_text','footer_left','footer_center','footer_right'].map(key=>[key,f.elements['document_'+key].value]));document.querySelector('#document-preview').innerHTML=examDocumentHeader({...editor,title:f.elements.title.value})+examDocumentFooter(editor);}if(el.id==='catalog-search'){const q=el.value.toLocaleLowerCase();document.querySelector('#exam-grid').innerHTML=examCards(catalog.filter(e=>(e.title+' '+e.category).toLocaleLowerCase().includes(q)))}if(el.dataset.q&&current?.token){current.answers=collected();updateProgress();scheduleSave()}});
document.addEventListener('change',async event=>{const el=event.target;if(el.id==='participant-type'){const payroll=document.querySelector('#payroll');payroll.required=el.value==='employee';payroll.closest('label').firstChild.textContent=el.value==='employee'?'Número de nómina':'Referencia de postulante (opcional)'}
 if(el.dataset.question&&['type','options','rows','columns'].includes(el.dataset.prop)){const q=editor.questions.find(q=>q.id===el.dataset.question);const oldType=q.type;gatherEditor();if(q.type!==oldType)q.correct=null;paintEditor()}
 if(el.dataset.keyToggle){gatherEditor();const q=editor.questions.find(q=>q.id===el.dataset.keyToggle);q.correct=el.checked?(['matching','table'].includes(q.type)?{}:q.type==='multiple'?[]:''):null;paintEditor()}
 if(el.dataset.upload&&el.files[0]){try{gatherEditor();const file=el.files[0];if(file.size>5_000_000)throw Error('La imagen debe pesar hasta 5 MB.');const base=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result.split(',')[1]);reader.onerror=reject;reader.readAsDataURL(file)});const r=await api('/admin/upload','POST',{data:base});editor.questions.find(q=>q.id===el.dataset.upload).image=r.url;paintEditor()}catch(e){error(e.message)}}});
document.addEventListener('click',async event=>{const mark=event.target.closest('[data-mark]');if(mark&&current?.token){const qid=mark.dataset.mark;const label=document.querySelector(`[data-mark-label="${qid}"]`).value.trim();const question=current.exam.questions.find(q=>q.id===qid);if(question.mark_labels&&!label){toast('Escribe primero el nombre de la parte que vas a marcar.');return}const r=mark.getBoundingClientRect();const marks=current.answers[qid]||[];if(marks.length<20){marks.push({x:Math.max(0,Math.min(1,(event.clientX-r.left)/r.width)),y:Math.max(0,Math.min(1,(event.clientY-r.top)/r.height)),label});current.answers[qid]=marks;renderMarks(qid);updateProgress();scheduleSave()}return}const b=event.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;try{
 if(action==='attempt-history'){const archived=b.dataset.archived==='true';dialog.innerHTML=`<h2>${archived?'Eliminar del historial':'Restaurar evaluación'}</h2><p>${archived?'La evaluación dejará de contar en los resultados y dashboards vigentes. Podrás restaurarla desde el filtro Eliminados del historial.':'La evaluación volverá a contar en resultados y dashboards.'}</p><div id="user-form-error"></div><form id="attempt-history-form"><input type="hidden" name="attempt_id" value="${b.dataset.id}"><input type="hidden" name="archived" value="${archived}"><label class="field">Motivo<textarea name="reason" required maxlength="2000"></textarea></label><div class="actions"><button type="button" data-action="close-dialog">Cancelar</button><button class="primary">${archived?'Eliminar del historial':'Restaurar'}</button></div></form>`;dialog.showModal()}
 if(action==='payroll-results'){activeQuery='?payroll='+encodeURIComponent(b.dataset.payroll);history.replaceState(null,'','#results');await renderResults(activeQuery)}
 if(action==='clear-filters'){if(location.hash.startsWith('#dashboard'))await renderDashboard();else await renderResults()}
 if(action==='new-user')userDialog();
 if(action==='edit-user')userDialog(managedUsers.find(u=>u.id===Number(b.dataset.id)));
 if(action==='logout'){await api('/logout','POST',{});session={authenticated:false};adminCatalog=[];location.hash='#inicio'}
 if(action==='refresh')await route();
 if(action==='close-dialog')dialog.close();
 if(action==='download-pdf'){await downloadEvaluationPdf(b);return}
 if(action==='print')window.print();
 if(action==='password'){dialog.innerHTML=`<h2>Cambiar contraseña</h2><form id="password-form">${field('Contraseña actual','current','','password','required autocomplete="current-password"')}${field('Nueva contraseña (mínimo 10 caracteres)','password','','password','required minlength="10" autocomplete="new-password"')}<div class="actions"><button type="button" data-action="close-dialog">Cancelar</button><button class="primary">Guardar contraseña</button></div></form>`;dialog.showModal()}
 if(action==='share'){await navigator.clipboard.writeText(location.origin+'/#exam/'+b.dataset.id);toast('Enlace copiado para compartir.')}
 if(action==='archive'){await api('/admin/exams/'+b.dataset.id+'/archive','POST',{});await renderExamList()}
 if(['add-q','remove-q','move-q','remove-image'].includes(action)){gatherEditor();if(action==='add-q')editor.questions.push(newQuestion(b.dataset.type));if(action==='remove-q'){if(editor.questions.length===1)throw Error('Conserva al menos una pregunta.');editor.questions=editor.questions.filter(q=>q.id!==b.dataset.id)}if(action==='move-q'){const i=editor.questions.findIndex(q=>q.id===b.dataset.id),j=i+Number(b.dataset.delta);if(j>=0&&j<editor.questions.length)[editor.questions[i],editor.questions[j]]=[editor.questions[j],editor.questions[i]]}if(action==='remove-image')delete editor.questions.find(q=>q.id===b.dataset.id).image;paintEditor()}
 if(action==='clear-marks'){current.answers[b.dataset.id]=[];renderMarks(b.dataset.id);updateProgress();scheduleSave()}
 if(action==='add-mark'){const id=b.dataset.id,x=document.querySelector(`[data-x="${id}"]`).value,y=document.querySelector(`[data-y="${id}"]`).value,label=document.querySelector(`[data-mark-label="${id}"]`).value.trim();if(current.exam.questions.find(q=>q.id===id).mark_labels&&!label)throw Error('Escribe una etiqueta para la marca.');if(x===''||y===''||Number(x)<0||Number(x)>100||Number(y)<0||Number(y)>100)throw Error('Escribe dos coordenadas entre 0 y 100.');const marks=current.answers[id]||[];if(marks.length>=20)throw Error('Puedes añadir hasta 20 marcas.');marks.push({x:Number(x)/100,y:Number(y)/100,label});current.answers[id]=marks;renderMarks(id);updateProgress();scheduleSave()}
 if(action==='submit-final'){b.disabled=true;clearTimeout(autosaveTimer);await api('/attempts/'+current.token+'/submit','POST',{answers:current.answers});dialog.close();location.hash='#done/'+current.token}
 }catch(e){toast(e.message)}finally{b.disabled=false}});
function renderMarks(id){const container=document.querySelector('#question-'+id);const area=container.querySelector('.mark-area');area.querySelectorAll('.mark-dot').forEach(n=>n.remove());area.insertAdjacentHTML('beforeend',(current.answers[id]||[]).map((p,i)=>`<span class="mark-dot" style="left:${p.x*100}%;top:${p.y*100}%">${i+1}</span>`).join(''));container.querySelector('[data-labels]').innerHTML=(current.answers[id]||[]).map((p,i)=>p.label?`<small>${i+1}. ${esc(p.label)}</small><br>`:'').join('');container.querySelector('[data-action="clear-marks"]').textContent=`Borrar marcas (${current.answers[id].length})`}
window.addEventListener('hashchange',route);route();
